import {mapsRequest,validPlace,placeLink} from './maps-api.js';
export const bookingProviders=[{name:'大众点评',href:'https://www.dianping.com/',purpose:'查看餐厅评价',connected:false},{name:'同程旅行',href:'https://www.ly.com/',purpose:'查询住宿与预订',connected:false},{name:'携程旅行',href:'https://www.ctrip.com/',purpose:'查询住宿与预订',connected:false}];
export function createDiscovery({e,btn,icon,currentTrip,currentDay,onPick,toast}){
  let category='餐饮',results=[],op=null;
  function dispose(){op?.abort();op=null;}
  function page(){
    const t=currentTrip(),near=t.days[currentDay()].items.find(x=>validPlace(x.place))?.place;
    return `<section class="discovery-page"><div class="page-head"><div><h1>美食 · 住宿</h1><p class="muted">围绕行程，找一家小馆或一晚好住处</p></div></div><div class="segmented section-space">${btn('找美食','discovery-type',category==='餐饮'?'primary':'secondary','food','data-type="餐饮"')}${btn('找住宿','discovery-type',category==='住宿'?'primary':'secondary','bed','data-type="住宿"')}</div><form data-form="discovery" class="card flat section-space"><div class="form-grid"><label class="field">城市<input name="city" value="${e(t.city)}" maxlength="30" required></label><label class="field">关键词<input name="keywords" value="${category==='餐饮'?'当地美食':'酒店'}" maxlength="60" required></label>${near?`<label class="choice field full"><input type="checkbox" name="near" value="yes">在第 ${currentDay()+1} 天已确认地点附近查找（10 公里内）</label>`:''}</div><p class="hint section-space">地点来源：高德。不含大众点评评分、实时房价或可订库存。</p><p class="form-error" role="alert"></p><div class="form-actions"><button class="btn primary" type="submit">${icon('pin')}查找${category==='餐饮'?'美食':'住宿'}</button></div></form><div id="discovery-results" class="favorite-grid section-space" aria-live="polite"></div><div class="section-space"><h2>到官方平台核实</h2><p class="hint">以下平台尚未连接数据服务；可前往官网查看评价、价格与预订条件。</p><div class="provider-grid">${bookingProviders.map(p=>`<a class="card flat provider-card" href="${p.href}" target="_blank" rel="noopener noreferrer"><strong>${p.name}</strong><p class="hint">${p.purpose}</p><span class="pill">官网查询 · 数据待接入</span></a>`).join('')}</div></div></section>`;
  }
  async function submit(form){
    dispose();op=new AbortController();const operation=op,data=new FormData(form),error=form.querySelector('.form-error'),button=form.querySelector('[type="submit"]'),node=document.querySelector('#discovery-results');results=[];error.textContent='';node.textContent='正在查询高德地点…';button.disabled=true;
    const near=currentTrip().days[currentDay()].items.find(x=>validPlace(x.place))?.place;
    const body={category:category==='餐饮'?'food':'stay',city:String(data.get('city')||''),keywords:String(data.get('keywords')||''),...(data.get('near')&&near?{location:near.location,radius:10000}:{})};
    try{const response=await mapsRequest('search',{body,signal:operation.signal});if(operation.signal.aborted||!form.isConnected)return;results=response.places.filter(validPlace);node.innerHTML=results.length?results.map((p,i)=>`<article class="card flat"><span class="pill">${category==='餐饮'?'美食地点':'住宿地点'} · 高德</span><h3 class="section-space">${e(p.name)}</h3><p class="hint">${e(p.city+' '+p.district+' '+p.address)}</p><div class="form-actions"><a class="btn secondary" href="${e(placeLink(currentTrip().city,{title:p.name,place:p}))}" target="_blank" rel="noopener noreferrer">地图查看</a>${btn('加入当天','discovery-pick','soft','plus',`data-index="${i}"`)}</div></article>`).join(''):'<p class="hint">没有找到地点，试试其他关键词或范围。</p>';}catch(err){if(!operation.signal.aborted&&form.isConnected){node.textContent='';error.textContent=err.message||'地点查询暂不可用';}}finally{if(form.isConnected)button.disabled=false;}
  }
  return {page,dispose,handleSubmit(form){if(form.dataset.form!=='discovery')return false;submit(form);return true;},actions:{'discovery-type':el=>{category=el.dataset.type;dispose();return category;},'discovery-pick':el=>{const p=results[Number(el.dataset.index)];if(validPlace(p))onPick(p,category);else toast('请重新搜索地点');}}};
}
